import{z as r,x as d,o as t,c as p,q as A,j as s,D as l,d as e,s as i,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"JWT 陷阱","description":"","frontmatter":{"title":"JWT 陷阱","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/jwt-pitfalls.md","filePath":"cs/jwt-pitfalls.md","lastUpdated":1791413859000}'),B={name:"cs/jwt-pitfalls.md"};function c(C,a,u,m,h,f){const o=d("Mermaid");return t(),p("div",null,[a[2]||(a[2]=A('<h1 id="jwt-陷阱" tabindex="-1">JWT 陷阱 <a class="header-anchor" href="#jwt-陷阱" aria-label="Permalink to &quot;JWT 陷阱&quot;">​</a></h1><div class="epigraph"><p>JWT 把声明做成可验的紧凑串。陷阱是算法可切换成 none、用对称密钥去验非对称、不验 aud/exp，于是「有令牌」再次变成装饰。</p><footer>—— RFC 7519；RFC 7515 JWS；Jones、Bradley 与 Sakimura；对照 auth0/jwt 误用报告一类公开分析</footer></div><p>上一课<a href="/cs/arp-spoofing">ARP</a>结束信道映射。身份课序从<strong>应用令牌</strong>起。主干会话可能已有 cookie；JWT 常被当成无状态银弹。缺口是声明合同与算法混淆，不给伪造步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>alg=none</code>、把公钥当 HMAC 密钥、不检查 <code>iss</code>/<code>aud</code>、过长有效期、把权限写进不可吊销的胖令牌。缺口是验证库的默认值，不是 JSON 语法。</p><p><span class="marginnote">术语翻译：声明（claim）就是令牌里「我担保你是谁、权限到什么时候」的键值对，像一张盖了章的工牌——门禁读的是章上的部门和有效期，而不是重新盘问你本人。</span></p><h3 id="签名-加密" tabindex="-1">签名≠加密 <a class="header-anchor" href="#签名-加密" aria-label="Permalink to &quot;签名≠加密&quot;">​</a></h3><p>JWS 可验不可隐藏。敏感声明要 JWE 或根本不要放进去。</p><p><span class="marginnote">RFC 7519。本课禁止构造恶意 JWT 的操作指导。密钥轮换与 <code>kid</code> 注入是实现问题：只接受已知 kid。</span></p><p><span class="marginnote">常见误区：以为令牌「签过名」别人就看不到内容。实际上 JWS 的 payload 只是 Base64URL 编码，随手可解——把身份证号、手机号塞进去等于明文广播；要保密得用 JWE 加密。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列出必须检查的头与声明。对照服务端会话：可吊销、可短。JWT 适合短命访问令牌，刷新走服务端。下一课会话管理把 cookie 旗标收全。</p>',13)),(t(),s(n,null,{default:l(()=>[i(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20TOK%5B%22JWT%22%5D%20--%3E%20ALG%5B%22%E9%92%89%E6%AD%BB%E5%85%81%E8%AE%B8%E7%AE%97%E6%B3%95%22%5D%0A%20%20TOK%20--%3E%20SIG%5B%22%E7%94%A8%E6%AD%A3%E7%A1%AE%E5%AF%86%E9%92%A5%E9%AA%8C%E7%AD%BE%22%5D%0A%20%20SIG%20--%3E%20CLAIM%5B%22iss%20aud%20exp%20nbf%22%5D%0A%20%20CLAIM%20--%3E%20OK%5B%22%E6%8E%A5%E5%8F%97%E5%A3%B0%E6%98%8E%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("无状态的代价是吊销难。证明在「验签+声明」游戏内；"),E("code",null,"none"),e(" 与错钥是游戏外。OAuth 后课会发这种令牌——先把验法钉死。")],-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},[e("数字实例："),E("code",null,"exp"),e(" 是 Unix 时间戳，比如 "),E("code",null,"exp = 1767225600"),e(" 表示 2026-01-01 零点 UTC 后作废。把有效期写成一年，等于把令牌泄漏后的可利用窗口放大一整年；短命令牌加刷新机制才是常规做法。")])],-1)),(t(),s(n,null,{default:l(()=>[i(o,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20V%5B%22%E9%AA%8C%E8%AF%81%E5%BA%93%E6%94%B6%E5%88%B0%E4%BB%A4%E7%89%8C%22%5D%20--%3E%20H%5B%22%E8%AF%BB%E5%A4%B4%E9%87%8C%E7%9A%84%20alg%22%5D%0A%20%20H%20--%3E%7C%22alg%20%3D%20none%22%7C%20N%5B%22%E8%B7%B3%E8%BF%87%E9%AA%8C%E7%AD%BE%EF%BC%8C%E7%9B%B4%E6%8E%A5%E4%BF%A1%E5%A3%B0%E6%98%8E%22%5D%0A%20%20H%20--%3E%7C%22alg%20%3D%20HS256%22%7C%20K%5B%22%E7%94%A8%E5%93%AA%E4%B8%AA%E5%AF%86%E9%92%A5%E9%AA%8C%EF%BC%9F%22%5D%0A%20%20K%20--%3E%7C%22%E8%AF%AF%E7%94%A8%E5%85%AC%E9%92%A5%E5%BD%93%20HMAC%20%E5%AF%86%E9%92%A5%22%7C%20W%5B%22%E4%BC%AA%E9%80%A0%E4%BB%A4%E7%89%8C%E4%B9%9F%E8%83%BD%E9%80%9A%E8%BF%87%22%5D%0A%20%20K%20--%3E%7C%22%E6%AD%A3%E7%A1%AE%E7%9A%84%E5%AF%B9%E7%A7%B0%E5%AF%86%E9%92%A5%22%7C%20R%5B%22%E9%AA%8C%E7%AD%BE%E6%9C%89%E6%95%88%22%5D%0A%20%20R%20--%3E%20C%5B%22%E5%86%8D%E6%9F%A5%20iss%20%2F%20aud%20%2F%20exp%22%5D%0A%20%20C%20--%3E%20OK%5B%22%E6%8E%A5%E5%8F%97%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写全部 JOSE 算法套件。会话管理下一课：cookie、CSRF、固定。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>信道映射之后，应用身份常是 JWT。</li><li>钉算法、验签、验 aud/exp；JWS 不保密。</li><li>胖令牌难吊销；宜短命。</li><li>下一课会话管理。</li><li>出处：RFC 7519；RFC 7515；对照 OWASP 对 JWT 的讨论（机制，非利用手册）。</li></ul>',4))])}const F=r(B,[["render",c]]);export{T as __pageData,F as default};
